// Gráficos
new Chart(document.getElementById("graficoStatus"), {
  type: "doughnut",
  data: {
    labels: data.status.map(s => s.Status),
    datasets: [{
      data: data.status.map(s => s.Ocorrências),
      backgroundColor: ["#4fc3f7", "#ffca28", "#66bb6a", "#ef5350", "#ab47bc"]
    }]
  },
  options: {
    plugins: {
      legend: {
        position: 'bottom',
        labels: { color: "#fff", boxWidth: 12 }
      }
    }
  }
});

new Chart(document.getElementById("graficoEmpresas"), {
  type: "line",
  data: {
    labels: data.empresas.map(e => e.Empresa),
    datasets: [{
      label: "Ocorrências por Empresa",
      data: data.empresas.map(e => e.Frequência),
      borderColor: "#00BFFF",
      backgroundColor: "rgba(0,191,255,0.2)",
      tension: 0.4,
      fill: true,
      pointBackgroundColor: "#00BFFF"
    }]
  },
  options: {
    plugins: { legend: { display: false } },
    scales: {
      x: { ticks: { color: "#fff" } },
      y: { ticks: { color: "#fff" } }
    }
  }
});

