// Tabela
const tbody = document.querySelector("#tabelaRelatorio tbody");
data.relatorio.forEach(item => {
  let status = (item["Status"] || "").trim();
  let statusClass = status.replace(/\s+/g, '');
  let badge = `<span class='badge ${statusClass}'>${status}</span>`;
  tbody.innerHTML += `<tr>
    <td>${item["Data Formatada"] || ""}</td>
    <td>${item["Empresa"] || ""}</td>
    <td>${item["Descrição"] || ""}</td>
    <td>${badge}</td>
    <td>${item["Prioridade"] || ""}</td>
  </tr>`;
});
$(document).ready(function() {
  $('#tabelaRelatorio').DataTable({ responsive: true });
});
